self.addEventListener('install', function(event) {
  event.waitUntil((async function() {
    const cache = await caches.open(CACHE);
    const scope = self.registration.scope;
    const urls = ASSETS.map(function(path) {
      return new URL(path, scope).href;
    });
    // Cache in small batches.  One missing optional file must not abort the
    // whole installation (for example, third-party/ is not committed).
    for (let i = 0; i < urls.length; i += 8) {
      await Promise.all(urls.slice(i, i + 8).map(async function(url) {
        try {
          await cache.add(url);
        } catch (error) {
          console.warn('Offline cache skipped:', url, error);
        }
      }));
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', function(event) {
  event.waitUntil((async function() {
    const keys = await caches.keys();
    await Promise.all(keys.map(function(key) {
      if (key !== CACHE && key.indexOf('blockly-games-') === 0) {
        return caches.delete(key);
      }
      return Promise.resolve();
    }));
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', function(event) {
  const request = event.request;
  if (request.method !== 'GET') {
    return;
  }
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) {
    return;
  }

  if (request.mode === 'navigate') {
    // Network first so a fresh deployment is picked up, cache first when the
    // tablet is offline.
    event.respondWith((async function() {
      const cache = await caches.open(CACHE);
      try {
        // Bypass the HTTP cache as well: otherwise GitHub Pages can hand back
        // an old index after a deployment.
        const response = await fetch(request, {cache: 'no-store'});
        if (response && response.ok) {
          cache.put(request, response.clone());
          return response;
        }
        throw new Error('HTTP ' + response.status);
      } catch (error) {
        // Ignore ?level=... / ?lang=... when matching the cached shell: the
        // game reads those parameters from the real URL after the page loads.
        const hit = await cache.match(request, {ignoreSearch: true});
        if (hit) {
          return hit;
        }
        const index = await cache.match(
            new URL('index.html', self.registration.scope).href);
        return index || Response.error();
      }
    })());
    return;
  }

  event.respondWith((async function() {
    const cache = await caches.open(CACHE);
    const hit = await cache.match(request, {ignoreSearch: true});
    if (hit) {
      return hit;
    }
    try {
      const response = await fetch(request);
      if (response && response.ok) {
        cache.put(request, response.clone());
      }
      return response;
    } catch (error) {
      return Response.error();
    }
  })());
});
